<form class="module-card" method="post" enctype="multipart/form-data" action="<?=url('/admin/recorded-lectures')?>"><?=csrf_field()?><header class="module-card__header"><h2>Add Lecture</h2></header><div class="module-card__body"><div class="module-form-grid module-form-grid--three">
<div class="module-field"><label>Audience</label><select class="module-select" id="lectureAudience" name="audience_type"><option value="all">All students</option><option value="class" selected>Specific class</option><option value="student">Specific student</option></select></div>
<fieldset class="module-field field--wide" data-lecture-class><legend>Select one or more classes</legend><div class="live-class-picker__options"><?php foreach($classes as$c):?><label class="live-class-picker__option"><input type="checkbox" name="class_ids[]" value="<?=$c['id']?>"><span><?=e($c['name'])?></span></label><?php endforeach?></div></fieldset>
<div class="module-field" data-lecture-student hidden><label>Student</label><select class="module-select" name="student_id"><option value="">-- Select a student --</option><?php foreach($students as$s):?><option value="<?=$s['id']?>"><?=e($s['student_name'].' · '.$s['registration_no'].' · '.$s['class_name'])?></option><?php endforeach?></select></div>
