<?php $lectureSubjects=array_values(array_unique(array_map(static fn($l)=>$l['subject_name']??'General',$lectures)));sort($lectureSubjects);?><section class="module-card"><header class="module-card__header"><h2>Lectures</h2></header><div class="module-card__body"><?php if($lectures):?><div class="lectures-admin-filters" style="display:flex;flex-wrap:wrap;gap:10px;margin-bottom:14px"><input class="module-input" type="search" placeholder="Search title or chapter" data-lf-search style="flex:1 1 220px"><select class="module-select" data-lf-subject style="width:auto" aria-label="Filter by subject"><option value="">All subjects</option><?php foreach($lectureSubjects as$ls):?><option><?=e($ls)?></option><?php endforeach?></select><select class="module-select" data-lf-class style="width:auto" aria-label="Filter by class"><option value="">All classes</option><?php foreach($classes as$c):?><option><?=e($c['name'])?></option><?php endforeach?></select><input class="module-input" type="month" data-lf-month style="width:auto" aria-label="Filter by month"></div><?php endif?><div class="table-scroll"><table class="data-table"><thead><tr><th>Date</th><th>Title</th><th>Audience</th><th>Subject</th><th>Source</th><th>Status</th><?php if($canManage):?><th>Action</th><?php endif?></tr></thead><tbody><?php foreach($lectures as$l):$audience=$l['audience_type']==='all'?'All students':($l['audience_type']==='student'?($l['student_name']??'Student'):($l['class_names']??'Class'));?><tr data-lf-row data-subject="<?=e($l['subject_name']??'General')?>" data-classes="<?=e('|'.str_replace(', ','|',(string)($l['class_names']??'')).'|')?>" data-all="<?=$l['audience_type']==='all'?1:0?>" data-date="<?=e($l['publish_date'])?>" data-text="<?=e(mb_strtolower($l['title'].' '.($l['chapter']??'')))?>"><td><?=e($l['publish_date'])?></td><td><strong><?=e($l['title'])?></strong><br><small><?=e($l['chapter']??'')?></small></td><td><?=e($audience)?></td><td><?=e($l['subject_name']??'General')?></td><td><a class="btn btn--secondary btn--sm" href="<?=url('/admin/recorded-lectures/'.$l['id'])?>"><i data-lucide="play"></i>Watch</a><br><small><?=$l['video_path']?'Uploaded video':e(\App\Support\LectureMedia::providerLabel($l['video_url']))?></small></td><td><span class="status-badge status-badge--<?=e($l['status'])?>"><?=e(ucfirst($l['status']))?></span></td><?php if($canManage):?><td><form method="post" action="<?=url('/admin/recorded-lectures/'.$l['id'].'/delete')?>" onsubmit="return confirm('Delete this lecture?')"><?=csrf_field()?><button class="class-action-button class-action-button--danger" aria-label="Delete lecture"><i data-lucide="trash-2"></i></button></form></td><?php endif?></tr><?php endforeach?><?php if(!$lectures):?><tr><td colspan="7"><div class="compact-empty"><h3>No lectures yet</h3><p>Uploaded videos and shared links will appear here.</p></div></td></tr><?php endif?></tbody></table></div></div></section>
</div></div></main>
<?php if($canManage):?><script>document.addEventListener('DOMContentLoaded',()=>{const a=document.getElementById('lectureAudience'),c=document.querySelector('[data-lecture-class]'),s=document.querySelector('[data-lecture-student]');const sync=()=>{c.hidden=a.value!=='class';s.hidden=a.value!=='student';s.querySelector('select').required=a.value==='student'};a.addEventListener('change',sync);sync()});</script><?php endif?>
<script>document.addEventListener('DOMContentLoaded',()=>{const q=document.querySelector('[data-lf-search]');if(!q)return;const sub=document.querySelector('[data-lf-subject]'),cls=document.querySelector('[data-lf-class]'),mon=document.querySelector('[data-lf-month]'),rows=[...document.querySelectorAll('[data-lf-row]')];const apply=()=>{const t=q.value.trim().toLowerCase();rows.forEach(r=>{r.hidden=!((!t||r.dataset.text.includes(t))&&(!sub.value||r.dataset.subject===sub.value)&&(!cls.value||r.dataset.all==='1'||r.dataset.classes.includes('|'+cls.value+'|'))&&(!mon.value||r.dataset.date.startsWith(mon.value)))})};[q,sub,cls,mon].forEach(x=>x.addEventListener('input',apply))});</script>
